def largest(xs):
    if not xs:
        return None
    best = xs[0]
    for value in xs[1:]:
        if value > best:
            best = value
    return best

def count_vowels(text):
    total = 0
    for ch in text:
        if ch in "aeiou":
            total += 1
    return total

def second_smallest(xs):
    ordered = sorted(xs)
    if len(ordered) < 2:
        return None
    return ordered[1]
